From 91e9b9fc40a80584cd50e93f9ac982d5b377bf5b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:26:48 +0100
Subject: [PATCH] applets/appmenu: keep menus within the available screen
 height

Long menus were sized for the whole screen, so they got pushed past the
screen edge to stay clear of the panel, hiding their first items. Limit
menus and submenus to the available screen height so they scroll.

BUG: 497515
---
 applets/appmenu/appmenuapplet.cpp | 31 +++++++++++++++++++++++++++++++
 applets/appmenu/appmenuapplet.h   |  4 ++++
 2 files changed, 35 insertions(+)

diff --git a/applets/appmenu/appmenuapplet.cpp b/applets/appmenu/appmenuapplet.cpp
index 79c29a7e32..150acdb389 100644
--- a/applets/appmenu/appmenuapplet.cpp
+++ b/applets/appmenu/appmenuapplet.cpp
@@ -18,6 +18,9 @@
 #include <QScreen>
 #include <QTimer>

+#include <Plasma/Containment>
+#include <Plasma/Corona>
+
 int AppMenuApplet::s_refs = 0;
 namespace
 {
@@ -144,6 +147,24 @@ void AppMenuApplet::onMenuAboutToHide()
     setCurrentIndex(-1);
 }

+void AppMenuApplet::onSubMenuAboutToShow()
+{
+    if (auto *menu = qobject_cast<QMenu *>(sender())) {
+        limitMenuHeight(menu);
+    }
+}
+
+void AppMenuApplet::limitMenuHeight(QMenu *menu)
+{
+    menu->setMaximumHeight(m_maxMenuHeight);
+    const auto actions = menu->actions();
+    for (QAction *action : actions) {
+        if (QMenu *subMenu = action->menu()) {
+            connect(subMenu, &QMenu::aboutToShow, this, &AppMenuApplet::onSubMenuAboutToShow, Qt::UniqueConnection);
+        }
+    }
+}
+
 Qt::Edges edgeFromLocation(Plasma::Types::Location location)
 {
     switch (location) {
@@ -227,6 +248,16 @@ void AppMenuApplet::trigger(QQuickItem *ctx, int idx)
             pos.setY(pos.y() + ctx->height());
         }

+        QRect availableRect;
+        if (Plasma::Containment *c = containment(); c && c->corona() && c->screen() >= 0) {
+            availableRect = c->corona()->availableScreenRect(c->screen());
+        }
+        if (!availableRect.isValid()) {
+            availableRect = ctx->window()->screen()->availableGeometry();
+        }
+        m_maxMenuHeight = availableRect.height();
+        limitMenuHeight(m_currentMenu);
+
         m_currentMenu->adjustSize();

         pos = QPoint(qBound(geo.x(), pos.x(), geo.x() + geo.width() - m_currentMenu->width()),
diff --git a/applets/appmenu/appmenuapplet.h b/applets/appmenu/appmenuapplet.h
index 7260514b34..a813dc61af 100644
--- a/applets/appmenu/appmenuapplet.h
+++ b/applets/appmenu/appmenuapplet.h
@@ -10,6 +10,7 @@

 #include <QAbstractItemModel>
 #include <QPointer>
+#include <QWidget>

 class QQuickItem;
 class QMenu;
@@ -66,9 +67,12 @@ private:
     QMenu *createMenu(int idx) const;
     void setCurrentIndex(int currentIndex);
     void onMenuAboutToHide();
+    void onSubMenuAboutToShow();
+    void limitMenuHeight(QMenu *menu);

     int m_currentIndex = -1;
     int m_viewType = FullView;
+    int m_maxMenuHeight = QWIDGETSIZE_MAX;
     QPointer<QMenu> m_currentMenu;
     QPointer<QMenu> m_sourceMenu;
     QPointer<QQuickItem> m_buttonGrid;
